import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.aggregation.*;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;

@Service
public class OrderAggregationService {

    private final MongoTemplate mongoTemplate;

    public OrderAggregationService(MongoTemplate mongoTemplate) {
        this.mongoTemplate = mongoTemplate;
    }

    public List<CustomerOrderCount> countOrdersPerCustomer() {
        Instant thirtyDaysAgo = Instant.now().minus(30, ChronoUnit.DAYS);

        MatchOperation match = Aggregation.match(
            Criteria.where("createdAt").gte(thirtyDaysAgo)
                    .and("status").ne("CANCELLED")
        );

        GroupOperation group = Aggregation.group("customerId")
            .count().as("orderCount")
            .sum("totalAmount").as("totalSpent");

        SortOperation sort = Aggregation.sort(
            org.springframework.data.domain.Sort.Direction.DESC, "orderCount"
        );

        Aggregation pipeline = Aggregation.newAggregation(match, group, sort);

        return mongoTemplate
            .aggregate(pipeline, "orders", CustomerOrderCount.class)
            .getMappedResults();
    }
}

// Result DTO
record CustomerOrderCount(String id, long orderCount, double totalSpent) {}

