import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class TransferService {

    private final AccountRepository accountRepo;
    private final TransactionLedgerRepository ledgerRepo;

    public TransferService(AccountRepository accountRepo,
                           TransactionLedgerRepository ledgerRepo) {
        this.accountRepo = accountRepo;
        this.ledgerRepo = ledgerRepo;
    }

    @Transactional  // atomic: both writes succeed or both roll back
    public void transfer(String fromId, String toId, double amount) {
        Account from = accountRepo.findById(fromId)
            .orElseThrow(() -> new IllegalArgumentException("Source account not found"));
        Account to = accountRepo.findById(toId)
            .orElseThrow(() -> new IllegalArgumentException("Destination account not found"));

        if (from.getBalance() < amount) {
            throw new IllegalStateException("Insufficient funds");
        }

        from.setBalance(from.getBalance() - amount);
        to.setBalance(to.getBalance() + amount);

        accountRepo.save(from);
        accountRepo.save(to);

        // If this throws, both account saves are rolled back
        ledgerRepo.save(new LedgerEntry(fromId, toId, amount));
    }
}

